import { MeshBasicNodeMaterial, PlaneGeometry, Mesh, Group, Color } from 'three/webgpu';
import { gsap } from 'gsap';

export function createNode(config, ctx) {
  const { Group: ThreeGroup, Mesh: ThreeMesh, PlaneGeometry: ThreePlaneGeometry } = ctx.THREE;

  // Create container
  const container = new ThreeGroup();

  // Track timelines for cleanup
  const activeTimelines = [];

  // 1. STAGE & BACKDROP
  // The studio backdrop (7x6 units at z=-2.5) with a vertical gradient using the spec colors
  const gradientColors = config.intent?.visualSpec?.colors ?? {
    ink: "#16161d",
    paper: "#e8ecf2",
    accent: "#ff2a38",
    surface: "#0b0b10"
  };

  const bgGeo = new ThreePlaneGeometry(7, 6);
  const bgMat = new MeshBasicNodeMaterial();
  bgMat.color.set(gradientColors.surface);
  const backdropMesh = new ThreeMesh(bgGeo, bgMat);
  backdropMesh.position.set(0, 0, -2.55);
  container.add(backdropMesh);

  // 2. MAIN CARD INTERACTIVE GROUP
  const cardGroup = new ThreeGroup();
  container.add(cardGroup);

  // Create the visual plate (as specified in render mode: plane)
  const plateGeo = new ThreePlaneGeometry(1.4, 0.82);
  const plateMat = new MeshBasicNodeMaterial({
    color: new Color(gradientColors.surface),
    transparent: true,
    opacity: 0.95
  });

  const plateMesh = new ThreeMesh(plateGeo, plateMat);
  cardGroup.add(plateMesh);

  // 3. TEXT RENDERING
  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  let headlineString = "Journal 3";
  for (const item of textItems) {
    if (item.role === 'headline' || item.text) {
      headlineString = item.text;
      break;
    }
  }

  // Create MSDF text using ctx.fontAtlas
  const textElement = ctx.fontAtlas.createText(headlineString, {
    fontSize: 0.1, // mapped from spec 39px with respectful scene scale
    color: gradientColors.paper,
    align: 'center'
  });
  // Center slightly within the panel
  textElement.position.set(0, -0.02, 0.02);
  cardGroup.add(textElement);

  // Decorative accent line indicating the "signal red" accent color of Nova Atelier World
  const accentGeo = new ThreePlaneGeometry(0.3, 0.015);
  const accentMat = new MeshBasicNodeMaterial({ color: new Color(gradientColors.accent) });
  const accentMesh = new ThreeMesh(accentGeo, accentMat);
  accentMesh.position.set(0, -0.2, 0.02);
  cardGroup.add(accentMesh);

  // Set explicit positions/scales from config
  const pos = config.scenePosition ?? { x: 3.2, y: 1, z: 0.06 };
  const rot = config.sceneRotation ?? { x: 0, y: 0, z: 0 };
  const scl = config.sceneScale ?? { x: 1, y: 1, z: 1 };

  container.position.set(pos.x, pos.y, pos.z);
  container.rotation.set(rot.x, rot.y, rot.z);
  container.scale.set(scl.x, scl.y, scl.z);

  // 4. LOAD IMAGE LAYER (imageUrl: /prism-mock/home/nodes/floating-accent.png)
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
      plateMat.map = texture;
      plateMat.needsUpdate = true;
    }).catch((err) => {
      console.warn("Failed loading texture", err);
    });
  }

  // 5. BEHAVIOR & INTERACTION
  // Create interactive bounding hit box
  const hitGeo = new ThreePlaneGeometry(1.5, 0.92);
  const hitMat = new MeshBasicNodeMaterial({ visible: false });
  const hitMesh = new ThreeMesh(hitGeo, hitMat);
  hitMesh.position.set(0, 0, 0.05);
  cardGroup.add(hitMesh);

  // Setup handlers on userData
  container.userData = {
    handlers: {
      pointerover: () => {
        // "interactive card: hover lift (rise-in)"
        const tl = gsap.timeline();
        tl.to(cardGroup.position, {
          y: 0.15,
          z: 0.1,
          duration: 0.4,
          ease: "power2.out"
        });
        tl.to(plateMat, {
          opacity: 1,
          duration: 0.25
        }, 0);
        activeTimelines.push(tl);
      },
      pointerout: () => {
        const tl = gsap.timeline();
        tl.to(cardGroup.position, {
          y: 0,
          z: 0,
          duration: 0.4,
          ease: "power3.out"
        });
        activeTimelines.push(tl);
      },
      pointerdown: () => {
        // "press-down on click"
        const tl = gsap.timeline();
        tl.to(cardGroup.scale, {
          x: 0.94,
          y: 0.94,
          z: 0.94,
          duration: 0.12,
          ease: "back.out(2)"
        });
        activeTimelines.push(tl);
      },
      pointerup: () => {
        const tl = gsap.timeline();
        tl.to(cardGroup.scale, {
          x: 1,
          y: 1,
          z: 1,
          duration: 0.2,
          ease: "power2.out"
        });
        activeTimelines.push(tl);

        // "emit:hub-journal.select"
        ctx.emit("hub-journal.select", { id: config.id ?? "journal-3" });
      }
    },
    cleanup: () => {
      // Clean up timelines
      activeTimelines.forEach((t) => t.kill());

      // Dispose materials & geometries
      bgGeo.dispose();
      bgMat.dispose();
      plateGeo.dispose();
      plateMat.dispose();
      accentGeo.dispose();
      accentMat.dispose();
      hitGeo.dispose();
      hitMat.dispose();
    }
  };

  return container;
}
